import 'package:dartz/dartz.dart';import 'package:dio/dio.dart';import '../../../../../../Core/Models/product_details_model.dart';import '../../../../../../Core/Storage/Remote/api_error_handler.dart';import '../../../../../Global/Authentication/data/entities/user_data_model.dart';import '../../data/data/home_data.dart';import '../../data/models/product_preview_entities.dart';import '../../data/repositories/home_repo.dart';class HomeRepoImpl extends HomeRepo {  @override  Future<Either<Failure, List<ProductPreviewEntities>>>      getProductIsFeatured() async {    try {      final response = await HomeData.getDataProductIsFeatured();      return right(response);    } catch (e) {      if (e is DioException) {        return left(ServerFailure.fromDioError(e));      } else {        return left(ServerFailure.fromResponse(e.hashCode, e));      }    }  }  @override  Future<Either<Failure, List<ProductPreviewEntities>>>      getProductIsPopular() async {    try {      final response = await HomeData.getDataProductIsPopular();      return right(response);    } catch (e) {      if (e is DioException) {        return left(ServerFailure.fromDioError(e));      } else {        return left(ServerFailure.fromResponse(e.hashCode, e));      }    }  }  @override  Future<Either<Failure, ProductDetailsModel>> getProductDetails(int id) async {    try {      final response = await HomeData.getProductsByID(id);      return right(response);    } catch (e) {      if (e is DioException) {        return left(ServerFailure.fromDioError(e));      } else {        return left(ServerFailure.fromResponse(e.hashCode, e));      }    }  }  @override  Future<Either<Failure, UserDataModel>> getUserDataModel() async {    try {      final response = await HomeData.getUserData();      return right(response);    } catch (e) {      if (e is DioException) {        return left(ServerFailure.fromDioError(e));      } else {        return left(ServerFailure.fromResponse(e.hashCode, e));      }    }  }}